package productui

import "sync"

var (
	defaultStylesheetOnce sync.Once
	defaultStylesheet     string
	platformStylesOnce    sync.Once
	platformStyles        string
)

// Stylesheet is the fixed platform stylesheet for the first product slice.
// Customer branding resolves semantic custom properties; it cannot replace
// focus, status, high-contrast, print, or responsive safety rules.
func Stylesheet() string {
	defaultStylesheetOnce.Do(func() {
		theme, _ := ResolveTheme(nil)
		defaultStylesheet = stylesheetForTheme(theme)
	})
	return defaultStylesheet
}

// StylesheetForTheme validates customer overrides and returns one complete,
// deterministic sheet suitable for CSP hashing. A later BrandPack service can
// call this boundary without allowing raw tenant CSS into the document.
func StylesheetForTheme(overrides map[string]string) (string, error) {
	theme, err := ResolveTheme(overrides)
	if err != nil {
		return "", err
	}
	return stylesheetForTheme(theme), nil
}

func stylesheetForTheme(theme Theme) string {
	platformStylesOnce.Do(func() {
		platformStyles = stylesheet + semanticThemeAliases + refinements + componentRefinements + responsiveGridFix + responsiveSafety + collapsibleNavigation + navigationEnhancements + liveDataRefinements + viewportShell + personProfileStyles + peopleDirectoryStyles + workflowHistoryStyles + photoStyles + profileDetailStyles + historyTableStyles + journeyIntegrationStyles + motionStyles + customerThemeStylesheet() + appearanceStyles + appearanceSwatchStyles + customerIdentityStyles + brandLogoStyles + compactBrandStyles + appearanceRobustnessStyles + localeStyles + localePreferenceStyles + accessibilityStyles + accessibilityLayoutStyles + accessibilityReviewStyles + localePreferenceAccessibilityStyles + interactionMotionStyles + navigationPolishStyles + navigationScrollbarStyles + navigationViewportStyles + navigationViewportXStyles + colorModeControlStyles + surfaceTokenCoverage + legacySurfaceCoverage + loadingProxyStyles + loadingLayoutOffsets + navigationSearchStyles + peopleSortFilterStyles + peopleQuickActionStyles + collectionControlStyles + uxReviewRefinements + responsiveComponentStyles + peopleStickyHeaderStyles + dataTableStyles + globalSearchStyles + historyNavigationStyles + popoverStyles + viewerProfileStyles + organizationMetadataStyles + organizationHierarchyStyles + organizationDisclosureStyles + organizationVisibilityStyles + roleAccessStyles + workerIDStyles + permissionBoundaryStyles + validationStyles + statusPresentationStyles + provenancePresentationStyles + myselfStyles + networkTransitionStyles + navigationInteractionRefinements + interactionThemeStyles + visualQARefinements + peopleActionColumnStyles + contextSwitcherStyles + darkModeStyles
	})
	return theme.CSS() + platformStyles
}

