const stylesheet = `:root{color-scheme:light;font-family:"Segoe UI Variable","Segoe UI",system-ui,sans-serif;--accent:#006b57;--accent-hover:#005344;--soft:#eaf3ef;--ink:#102238;--muted:#526171;--canvas:#fafaf7;--surface:#fff;--line:#d5ddd8;--warning:#925400;--warning-bg:#fff6df;--danger:#b42318;--radius:8px;--panel:12px}*{box-sizing:border-box}body{margin:0;background:var(--canvas);color:var(--ink);font-size:16px;line-height:1.5}a{color:inherit}button,input,select{font:inherit}button,a,summary{cursor:pointer}:focus-visible{outline:2px solid var(--ink);outline-offset:3px;box-shadow:0 0 0 3px #fff}.skip-link{position:fixed;left:16px;top:-80px;z-index:100;padding:10px 14px;background:#fff;border:2px solid var(--ink);border-radius:var(--radius)}.skip-link:focus{top:14px}.topbar{display:grid;grid-template-columns:232px minmax(220px,1fr) auto auto auto;gap:14px;align-items:center;min-height:81px;border-bottom:1px solid var(--line);background:#fff;padding-right:24px;position:sticky;top:0;z-index:20}.wordmark{height:81px;display:flex;align-items:center;padding:0 24px 0 32px;border-right:1px solid var(--line);font-size:1.3rem;font-weight:750;letter-spacing:-.045em;text-decoration:none;position:relative}.wordmark:before{content:"";position:absolute;left:18px;top:28px;bottom:28px;width:4px;background:var(--accent);border-radius:2px}.global-search input{width:100%;min-height:44px;padding:10px 14px;border:1px solid var(--line);border-radius:var(--radius);background:var(--canvas);color:var(--ink)}.button{display:inline-flex;align-items:center;justify-content:center;min-height:44px;padding:9px 16px;border:1px solid #7b8997;border-radius:var(--radius);font-size:.875rem;font-weight:650;text-decoration:none}.button.primary{background:var(--accent);border-color:var(--accent);color:#fff}.button.primary:hover{background:var(--accent-hover)}.button.secondary{background:#fff;color:var(--accent)}.button.secondary:hover{background:var(--soft)}.button.full{width:100%;margin-top:10px}.notifications{position:relative}.notifications summary{display:grid;place-items:center;min-width:44px;min-height:44px;font-size:0;list-style:none}.notifications summary:before{content:"●";font-size:20px;color:var(--ink)}.notifications summary:after{content:"";position:absolute;right:8px;top:8px;width:7px;height:7px;border:2px solid #fff;border-radius:50%;background:#b54708}.popover{position:absolute;right:0;top:50px;width:290px;padding:18px;background:#fff;border:1px solid var(--line);border-radius:var(--panel);box-shadow:0 18px 48px #10223822}.popover h2{font-size:1rem}.popover p{color:var(--muted)}.avatar{display:inline-grid;place-items:center;flex:none;width:38px;height:38px;border-radius:50%;border:1px solid #d5e6df;background:var(--soft);color:var(--accent);font-size:.75rem;font-weight:700}.avatar.large{width:46px;height:46px}.shell-grid{display:grid;grid-template-columns:232px minmax(0,1fr);min-height:calc(100vh - 81px)}.sidebar{display:flex;flex-direction:column;padding:26px 14px 18px;border-right:1px solid var(--line);background:#fff}.tenant{padding:0 12px 16px;color:var(--muted);font-size:.75rem}.sidebar ul{list-style:none;margin:0;padding:0}.nav-link{display:flex;align-items:center;gap:10px;min-height:46px;margin:3px 0;padding:10px 13px;border-radius:var(--radius);font-size:.875rem;font-weight:550;text-decoration:none}.nav-link:hover,.nav-link[aria-current=page]{background:var(--soft);color:var(--accent)}.nav-link[aria-current=page]{box-shadow:inset 3px 0 var(--accent);font-weight:700}.nav-count{margin-left:auto;padding:2px 7px;border-radius:6px;background:#f5f7f5;font-size:.75rem}.nav-bottom{display:grid;margin-top:auto}.main{width:100%;max-width:1500px;margin:0 auto;padding:32px 34px 22px}.page-head{display:flex;align-items:flex-start;justify-content:space-between;gap:20px;margin-bottom:30px}.page-head h1{margin:0;font-size:clamp(1.75rem,2.5vw,2.15rem);line-height:1.15;letter-spacing:-.04em}.subtitle,.muted{color:var(--muted)}.subtitle{margin:8px 0 0}.scope-wrap{display:grid;justify-items:end;gap:4px}.scope{display:inline-flex;align-items:center;min-height:42px;padding:8px 12px;border:1px solid var(--line);border-radius:var(--radius);background:#fff;font-size:.8125rem;font-weight:650;text-decoration:none}.scope-wrap>span{color:var(--muted);font-size:.75rem}.surface{min-width:0;border:1px solid var(--line);border-radius:var(--panel);background:#fff}.panel{margin-top:20px;overflow:hidden}.section-head{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:20px 22px 16px}.section-head h2{margin:0;font-size:1.125rem}.home-grid{display:grid;grid-template-columns:minmax(0,1.75fr) minmax(255px,1fr);gap:20px;align-items:start}.side-stack{display:grid;gap:20px}.work-list{overflow:hidden}.tabs{display:flex;gap:22px;padding:0 22px;border-bottom:1px solid var(--line)}.tab{padding:11px 0;border-bottom:2px solid transparent;color:var(--muted);font-size:.875rem;text-decoration:none}.tab.active{border-bottom-color:var(--accent);color:var(--accent);font-weight:700}.count{padding:3px 8px;border-radius:6px;background:#f1f4f1;color:var(--muted);font-size:.75rem}.work-row{display:flex;align-items:center;gap:14px;min-height:86px;padding:14px 22px;border-bottom:1px solid #e8ede9;text-decoration:none}.work-row:hover,.work-row.selected{background:var(--soft)}.work-row.selected{box-shadow:inset 3px 0 var(--accent)}.row-main{flex:1;min-width:0}.row-main strong,.row-main small,.person-line strong,.person-line small{display:block}.row-main small,.person-line small{color:var(--muted);font-size:.8125rem}.row-end{display:grid;justify-items:end;gap:5px;color:var(--muted);font-size:.8125rem}.status{display:inline-flex;align-items:center;width:max-content;padding:4px 8px;border-radius:6px;background:#eef1ef;color:var(--muted);font-size:.8125rem}.status.warning{background:var(--warning-bg);color:var(--warning)}.status.success,.positive{color:var(--accent)}.status.success{background:var(--soft)}.panel-foot{display:flex;align-items:center;justify-content:space-between;padding:13px 22px;color:var(--muted);font-size:.8125rem}.panel-foot a{color:var(--accent);font-weight:650;text-decoration:none}.coverage{padding:0 20px 18px}.person-line{display:flex;align-items:center;gap:12px;padding:14px 0;border-top:1px solid var(--line)}.callout{padding:12px 14px;border-left:3px solid var(--accent);border-radius:0 var(--radius) var(--radius) 0;background:var(--soft);color:var(--muted);font-size:.8125rem}.callout.warning{border-color:#bc7a16;background:#fff8e9;color:#865000}.quick-actions{display:grid;padding:0 14px 14px}.quick-actions a{min-height:47px;padding:12px 10px;color:var(--accent);font-size:.875rem;text-decoration:none}.quick-actions a:hover{background:var(--soft)}.recent .activity,.report-list .activity{border-top:1px solid var(--line)}.activity{display:flex;align-items:center;gap:12px;min-height:62px;padding:10px 22px}.activity>.check{display:grid;place-items:center;width:32px;height:32px;border-radius:50%;background:var(--soft);color:var(--accent)}.activity>small{color:var(--muted)}.workbench{display:grid;grid-template-columns:minmax(0,1.55fr) minmax(300px,1fr);gap:20px;align-items:start}.work-preview{position:sticky;top:101px;padding:22px}.preview-head{display:grid;grid-template-columns:auto minmax(0,1fr);gap:12px;padding-bottom:18px;border-bottom:1px solid var(--line)}.preview-head>.status{grid-column:2}.preview-head h2{margin:2px 0;font-size:1.125rem}.preview-head p{margin:0;font-size:.8125rem}.facts{padding:18px 0}.facts h3{margin:0 0 8px}.facts>div{display:flex;justify-content:space-between;gap:14px;padding:8px 0;font-size:.8125rem}.facts>div>span{color:var(--muted)}.facts>div>strong{text-align:right}.steps{display:grid;grid-template-columns:repeat(3,1fr);padding:18px 0;margin:0;border-top:1px solid var(--line);list-style:none}.steps li{text-align:center;color:var(--muted);font-size:.75rem}.steps .done,.steps .current{color:var(--accent)}.directory-tools,.toolbar{display:flex;align-items:center;justify-content:space-between;gap:14px;margin-bottom:16px}.directory-tools p{margin:2px 0}.people-workspace{display:grid;grid-template-columns:minmax(0,1fr) 325px;overflow:hidden;border:1px solid var(--line);border-radius:var(--panel);background:#fff}.people-columns,.people-row{display:grid;grid-template-columns:1.35fr 1.2fr 1fr 1.1fr .8fr;gap:10px;align-items:center}.people-columns{min-height:44px;padding:9px 17px;border-bottom:1px solid var(--line);background:#f5f7f5;color:var(--muted);font-size:.75rem;font-weight:650}.people-row{min-height:65px;padding:9px 17px;border-bottom:1px solid var(--line);font-size:.8125rem;text-decoration:none}.people-row:hover,.people-row.selected{background:var(--soft)}.people-row.selected{box-shadow:inset 3px 0 var(--accent)}.person-cell,.person-head{display:flex;align-items:center;gap:10px}.person-context{padding:22px;border-left:1px solid var(--line);background:#fcfcfa}.person-head{padding-bottom:16px;border-bottom:1px solid var(--line)}.person-head h2,.person-head p{margin:0}.upcoming{display:grid;gap:4px;margin:12px 0;padding:13px;border:1px solid var(--line);border-radius:var(--radius)}.org{padding:0 22px 24px}.org-node{display:flex;align-items:center;gap:10px;width:min(285px,100%);min-height:67px;padding:12px;border:1px solid var(--line);border-radius:var(--radius);background:#fff}.org-node.leader{margin:10px auto 28px;background:var(--soft)}.org-branches{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}.org-node.manager{width:100%;box-shadow:inset 0 3px var(--accent)}.coverage-strip{display:flex;align-items:center;gap:22px;padding:0 22px 20px}.coverage-strip>p{flex:1}.coverage-strip>.button{flex:none}.metrics{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;margin-bottom:18px}.metric{padding:18px;border:1px solid var(--line);border-radius:var(--radius);background:#fff}.metric strong,.metric small{display:block}.metric strong{margin-top:7px;font-size:1.65rem}.metric small{color:var(--muted)}.insights-grid{display:grid;grid-template-columns:2fr 1fr;gap:18px}.bars{display:grid;gap:15px;padding:10px 22px 22px}.bars>div{display:grid;grid-template-columns:60px 1fr 28px;gap:10px;align-items:center;font-size:.75rem}.bar-track{height:19px;border-radius:4px;background:#edf1ee;overflow:hidden}.bar-fill{display:block;height:100%;background:linear-gradient(90deg,var(--accent) 0 72%,#8fb7ac 72% 92%,#d39a3c 92%)}.width-58{width:58%}.width-61{width:61%}.width-67{width:67%}.width-72{width:72%}.definition{padding:12px;background:#f3f6f3;color:var(--muted)}.admin-grid{display:grid;grid-template-columns:1fr 1fr;gap:18px}.admin-hero{grid-column:1/-1;display:flex;align-items:center;justify-content:space-between;gap:20px;padding:26px;background:linear-gradient(120deg,var(--soft),#fff 72%)}.admin-hero h2,.admin-hero p{margin:4px 0}.admin-card{display:grid;grid-template-columns:1fr auto;gap:12px;padding:22px}.admin-card h3,.admin-card p{margin:0}.admin-card a{color:var(--accent);font-weight:650;text-decoration:none}.settings-shell{display:grid;grid-template-columns:210px minmax(0,1fr) 285px;overflow:hidden;border:1px solid var(--line);border-radius:var(--panel);background:#fff}.settings-nav,.settings-form,.settings-context{padding:22px}.settings-nav{display:flex;flex-direction:column;gap:3px;border-right:1px solid var(--line);background:#f8f9f7}.settings-nav strong{margin:11px 9px 4px;color:var(--muted);font-size:.75rem;letter-spacing:.07em}.settings-nav a{padding:9px;border-radius:var(--radius);font-size:.875rem;text-decoration:none}.settings-nav a:hover,.settings-nav a.active{background:var(--soft);color:var(--accent)}.settings-form{display:grid;gap:17px}.settings-form h2,.settings-form h3,.settings-form p{margin:0}.choice-grid{display:grid;grid-template-columns:1fr 1fr;gap:9px}.choice{display:grid;gap:3px;min-height:76px;padding:12px;border:1px solid var(--line);border-radius:var(--radius);background:#fff;color:var(--ink);text-align:left}.choice.active{border-color:var(--accent);background:var(--soft);box-shadow:inset 0 0 0 1px var(--accent)}.settings-form form{display:grid;grid-template-columns:1fr 1fr;gap:12px}.settings-form label{display:grid;gap:6px;color:var(--muted);font-size:.875rem}.settings-form select{min-width:0;min-height:44px;padding:8px;border:1px solid #7b8997;border-radius:var(--radius);background:#fff}.settings-form form .button{grid-column:1/-1}.settings-context{border-left:1px solid var(--line);background:#fcfcfa}.settings-context h2,.settings-context p{margin-top:0}.footer{display:flex;justify-content:space-between;gap:10px;margin-top:24px;color:var(--muted);font-size:.75rem}@media(max-width:1190px){.topbar{grid-template-columns:210px minmax(180px,1fr) auto auto auto}.shell-grid{grid-template-columns:210px}.main{padding:28px 22px}.settings-form form{grid-template-columns:1fr}.settings-form form .button{grid-column:1}.work-row .row-main small+small{display:none}}@media(max-width:990px){.home-grid,.workbench,.people-workspace,.settings-shell{grid-template-columns:1fr}.side-stack{grid-template-columns:1fr 1fr}.work-preview{position:static}.person-context,.settings-context{border-left:0;border-top:1px solid var(--line)}.settings-nav{flex-direction:row;flex-wrap:wrap;border-right:0;border-bottom:1px solid var(--line)}.settings-nav strong{display:none}}@media(max-width:760px){.topbar{position:static;grid-template-columns:1fr auto auto;padding:0 16px}.wordmark{height:65px;border:0;padding-left:16px}.wordmark:before{left:2px;top:20px;bottom:20px}.global-search{grid-column:1/-1;grid-row:2;padding-bottom:14px}.topbar>.button{display:none}.shell-grid{grid-template-columns:1fr}.sidebar{padding:10px 14px;border-right:0;border-bottom:1px solid var(--line)}.tenant{display:none}.sidebar nav:first-of-type{overflow:auto}.sidebar ul{display:flex;gap:4px}.nav-link{white-space:nowrap}.nav-bottom{display:none}.main{padding:23px 17px}.page-head{display:grid;margin-bottom:22px}.scope-wrap{justify-items:start}.home-grid,.side-stack,.insights-grid{grid-template-columns:1fr}.people-columns{display:none}.people-row{grid-template-columns:1.2fr 1fr}.people-row>span:nth-child(n+4){display:none}.people-row>span:nth-child(3){grid-column:2}.org-branches,.metrics,.admin-grid{grid-template-columns:1fr}.admin-hero{grid-column:1;align-items:flex-start;flex-direction:column}.coverage-strip,.toolbar,.directory-tools{align-items:stretch;flex-direction:column}.footer{display:grid}}@media(max-width:420px){.work-row{padding-inline:14px}.work-row>.avatar{display:none}.row-end{max-width:96px}.tabs{gap:16px;padding-inline:15px;overflow:auto}.activity{padding-inline:15px}.settings-form,.settings-context{padding:18px}.choice-grid{grid-template-columns:1fr}}@media(prefers-reduced-motion:reduce){*{scroll-behavior:auto!important;transition-duration:.01ms!important;animation-duration:.01ms!important}}@media(forced-colors:active){:root{--line:CanvasText}.nav-link[aria-current=page],.status,.surface,.people-workspace{border:1px solid CanvasText}}@media print{.topbar,.sidebar,.scope-wrap,.button,.notifications{display:none!important}.shell-grid{display:block}.main{max-width:none;padding:0}.surface,.people-workspace,.settings-shell{break-inside:avoid;border-color:#000}.footer{border-top:1px solid #000;padding-top:12px}}`
